-- Vendor registration: boat owners apply from a public page built in the
-- page builder (/jadi-vendor, VendorSignup block); admins review the
-- applications in Admin → Vendor applications, and approving one sends the
-- usual vendor invitation.
--
-- No anon policy: the public form posts to /api/vendor-applications, which
-- validates the input and writes with the service role.

create table if not exists vendor_applications (
  id uuid primary key default gen_random_uuid(),
  full_name text not null check (char_length(full_name) between 2 and 80),
  business_name text check (char_length(business_name) <= 120),
  email text not null check (email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' and char_length(email) <= 160),
  phone text not null check (phone ~ '^[0-9]{9,12}$'),
  jetty text check (char_length(jetty) <= 80),
  boat_count int check (boat_count between 1 and 50),
  boat_details text check (char_length(boat_details) <= 1000),
  message text check (char_length(message) <= 1000),
  source_page text check (char_length(source_page) <= 60),
  status text not null default 'new' check (status in ('new', 'approved', 'rejected')),
  admin_note text check (char_length(admin_note) <= 500),
  reviewed_by uuid references profiles(id) on delete set null,
  reviewed_at timestamptz,
  invite_id uuid references invites(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists vendor_applications_status on vendor_applications (status, created_at desc);

alter table vendor_applications enable row level security;
create policy "admin manages vendor applications" on vendor_applications
  for all using (private.is_operator()) with check (private.is_operator());

